def summary(prices):
    return sum(prices), len(prices)
total, n = summary([4500, 5000, 6500])
print(total, n)

def can_order(stock, name):
    if stock[name] > 0:
        return True
    return False
stock = {"coffee": 3, "latte": 0}
print(can_order(stock, "coffee"), can_order(stock, "latte"))

def discount_rate(total):
    if total >= 20000:
        return 10
    elif total >= 10000:
        return 5
    return 0
def pay(total):
    rate = discount_rate(total)
    sale = total * rate // 100
    return total - sale
print(pay(15500))
